//! The Falco catalogs, compiled in and parsed once per process.
//!
//! `catalogs/falco/` is generated by `scripts/sync_falco_catalog.py` from the
//! Falco field reference, the plugin READMEs, and the Falco default rules.
//! None of it is a closed list: an unknown field or name is a warning.

use serde::Deserialize;
use std::collections::{BTreeMap, BTreeSet, HashMap};
use std::sync::OnceLock;

const FIELDS_TOML: &str = include_str!(concat!(
    env!("OPENTIDE_ASSETS"),
    "/catalogs/falco/fields.toml"
));
const DEFAULTS_TOML: &str = include_str!(concat!(
    env!("OPENTIDE_ASSETS"),
    "/catalogs/falco/defaults.toml"
));
const EVENTS_TOML: &str = include_str!(concat!(
    env!("OPENTIDE_ASSETS"),
    "/catalogs/falco/events.toml"
));

/// The event source of a rule when its block does not name one.
pub const DEFAULT_SOURCE: &str = "syscall";

/// One event source (`syscall`, `k8s_audit`, ...).
#[derive(Debug, Clone, Deserialize)]
pub struct Source {
    pub name: String,
    pub plugin: String,
    pub description: String,
}

/// What a field holds, for operator and value checks.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Kind {
    String,
    Number,
    Bool,
    Ip,
    Other,
}

/// One Falco field.
#[derive(Debug, Clone, Deserialize)]
pub struct Field {
    pub name: String,
    #[serde(rename = "type")]
    pub field_type: String,
    pub kind: Kind,
    pub class: String,
    /// Event sources the field applies to; `*` is every source.
    pub sources: Vec<String>,
    /// Takes an argument: `proc.aname[2]`, `evt.arg.flags`.
    #[serde(default)]
    pub arg: bool,
    pub description: String,
}

impl Field {
    pub fn applies_to(&self, source: &str) -> bool {
        self.sources.iter().any(|s| s == "*" || s == source)
    }
}

/// A macro of the Falco default rules.
#[derive(Debug, Clone, Deserialize)]
pub struct Macro {
    pub name: String,
    pub condition: String,
    pub source: String,
    pub origin: String,
}

/// A list of the Falco default rules.
#[derive(Debug, Clone, Deserialize)]
pub struct List {
    pub name: String,
    pub items: Vec<String>,
    pub origin: String,
}

#[derive(Debug, Clone, Deserialize)]
struct Event {
    name: String,
    kind: String,
}

#[derive(Deserialize)]
struct FieldsFile {
    sources: Vec<Source>,
    fields: Vec<Field>,
}

#[derive(Deserialize)]
struct DefaultsFile {
    #[serde(default)]
    macros: Vec<Macro>,
    #[serde(default)]
    lists: Vec<List>,
}

#[derive(Deserialize)]
struct EventsFile {
    events: Vec<Event>,
}

/// Every Falco catalog.
pub struct Catalog {
    pub sources: Vec<Source>,
    pub fields: Vec<Field>,
    by_name: HashMap<String, usize>,
    pub macros: BTreeMap<String, Macro>,
    pub lists: BTreeMap<String, List>,
    events: BTreeMap<String, String>,
}

/// A field name, resolved for one event source.
#[derive(Debug, Clone, Copy)]
pub enum Lookup<'c> {
    /// The field, or the field whose argument the name carries
    /// (`evt.arg` for `evt.arg.flags`).
    Known(&'c Field),
    /// A field of another source.
    OtherSource(&'c Field),
    Unknown,
}

impl Catalog {
    pub fn cached() -> &'static Catalog {
        static CATALOG: OnceLock<Catalog> = OnceLock::new();
        CATALOG.get_or_init(|| {
            let fields: FieldsFile =
                toml::from_str(FIELDS_TOML).expect("catalogs/falco/fields.toml");
            let defaults: DefaultsFile =
                toml::from_str(DEFAULTS_TOML).expect("catalogs/falco/defaults.toml");
            let events: EventsFile =
                toml::from_str(EVENTS_TOML).expect("catalogs/falco/events.toml");
            let by_name = fields
                .fields
                .iter()
                .enumerate()
                .map(|(i, f)| (f.name.clone(), i))
                .collect();
            Catalog {
                sources: fields.sources,
                fields: fields.fields,
                by_name,
                macros: defaults
                    .macros
                    .into_iter()
                    .map(|m| (m.name.clone(), m))
                    .collect(),
                lists: defaults
                    .lists
                    .into_iter()
                    .map(|l| (l.name.clone(), l))
                    .collect(),
                events: events
                    .events
                    .into_iter()
                    .map(|e| (e.name, e.kind))
                    .collect(),
            }
        })
    }

    pub fn source(&self, name: &str) -> Option<&Source> {
        self.sources.iter().find(|s| s.name == name)
    }

    pub fn field(&self, name: &str) -> Option<&Field> {
        self.by_name.get(name).map(|&i| &self.fields[i])
    }

    /// Resolve `name` for `source`. A dotted name whose prefix is a field that
    /// takes an argument (`evt.arg.flags`, `evt.type.is.open`) is that field.
    pub fn lookup(&self, name: &str, source: &str) -> Lookup<'_> {
        let mut candidate = name;
        let mut exact = true;
        loop {
            if let Some(field) = self.field(candidate) {
                if exact || field.arg {
                    return if field.applies_to(source) {
                        Lookup::Known(field)
                    } else {
                        Lookup::OtherSource(field)
                    };
                }
            }
            match candidate.rsplit_once('.') {
                Some((head, _)) if head.contains('.') => {
                    candidate = head;
                    exact = false;
                }
                _ => return Lookup::Unknown,
            }
        }
    }

    /// Fields that apply to `source`, in name order.
    pub fn fields_for<'c>(&'c self, source: &'c str) -> impl Iterator<Item = &'c Field> + 'c {
        self.fields.iter().filter(move |f| f.applies_to(source))
    }

    /// The kind of event (`syscall`, `tracepoint`, `plugin`, `metaevents`), if known.
    pub fn event(&self, name: &str) -> Option<&str> {
        self.events.get(name).map(String::as_str)
    }

    pub fn events(&self) -> impl Iterator<Item = &str> {
        self.events.keys().map(String::as_str)
    }

    /// Names a source knows, for near-miss suggestions.
    pub fn field_names_for(&self, source: &str) -> BTreeSet<&str> {
        self.fields
            .iter()
            .filter(|f| f.applies_to(source))
            .map(|f| f.name.as_str())
            .collect()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn catalogs_load_with_every_source() {
        let c = Catalog::cached();
        for source in [
            "syscall",
            "k8s_audit",
            "aws_cloudtrail",
            "okta",
            "github",
            "gcp_auditlog",
        ] {
            assert!(c.source(source).is_some(), "{source}");
            assert!(c.fields_for(source).count() > 5, "{source}");
        }
        assert!(c.macros.contains_key("spawned_process"));
        assert!(c.lists.contains_key("shell_binaries"));
        assert_eq!(c.event("execve"), Some("syscall"));
    }

    #[test]
    fn lookup_resolves_arguments_and_sources() {
        let c = Catalog::cached();
        assert!(matches!(c.lookup("proc.name", "syscall"), Lookup::Known(_)));
        assert!(
            matches!(c.lookup("evt.arg.flags", "syscall"), Lookup::Known(f) if f.name == "evt.arg")
        );
        assert!(matches!(
            c.lookup("evt.time", "k8s_audit"),
            Lookup::Known(_)
        ));
        assert!(matches!(
            c.lookup("ka.verb", "syscall"),
            Lookup::OtherSource(_)
        ));
        assert!(matches!(c.lookup("proc.nmae", "syscall"), Lookup::Unknown));
        assert!(matches!(
            c.lookup("proc.name.extra", "syscall"),
            Lookup::Unknown
        ));
    }
}
